478 │   private async executeWithFailover<T>(
479 │     operationName: string,
480 │     operation: (endpoint: string) => Promise<T>
481 │   ): Promise<T> {
482 │     const total = this.endpoints.length;
483 │     let lastError: Error | null = null;
484 │ 
485 │     for (let attempt = 0; attempt < total; attempt++) {
486 │       const idx = (this.activeEndpointIndex + attempt) % total;
487 │       const currentEp = this.endpoints[idx];
488 │ 
489 │       try {
490 │         const result = await operation(currentEp);
491 │         if (idx !== this.activeEndpointIndex) {
492 │           console.warn(
493 │             pc.yellow(`\n⚡ Failover: Active inference endpoint switched to ${currentEp}`)
494 │           );
495 │           this.activeEndpointIndex = idx;
496 │         }
497 │         return result;
498 │       } catch (err: any) {
499 │         lastError = err;
500 │         if (err instanceof InferenceError && !err.failoverEligible) throw err;
501 │         if (total > 1 && attempt < total - 1) {
502 │           const nextIdx = (idx + 1) % total;
503 │           console.warn(
504 │             pc.dim(
505 │               `⚠️ [Failover] ${operationName} failed on ${currentEp} (${err.message}). Trying backup endpoint ${this.endpoints[nextIdx]}...`
506 │             )
507 │           );
508 │         }
509 │       }
510 │     }
511 │ 
512 │     throw (
513 │       lastError ||
514 │       new Error(
515 │         `All inference endpoints failed for ${operationName} (attempted: ${this.endpoints.join(", ")})`
516 │       )
517 │     );
518 │   }
