248	 248 │ /** Walk `err.cause` (and AggregateError members): fetch reports only "fetch failed"/"terminated" at the top. */
249	 249 │ export function transportCauseChain(err: any): TransportCause[] {
250	 250 │   const out: TransportCause[] = [];
251	 251 │   const seen = new Set<unknown>();
252	 252 │   const visit = (e: any): void => {
253	 253 │     if (!e || typeof e !== "object" || seen.has(e) || out.length >= 8) return;
254	 254 │     seen.add(e);
255	 255 │     const c: TransportCause = {};
256	 256 │     if (typeof e.name === "string") c.name = e.name;
257	 257 │     if (typeof e.code === "string") c.code = e.code;
258	 258 │     if (typeof e.errno === "number") c.errno = e.errno;
259	 259 │     if (typeof e.syscall === "string") c.syscall = e.syscall;
260	 260 │     if (typeof e.address === "string") c.address = e.address;
261	 261 │     if (typeof e.port === "number") c.port = e.port;
262	 262 │     if (typeof e.socket?.bytesWritten === "number") c.bytesWritten = e.socket.bytesWritten;
263	 263 │     if (typeof e.socket?.bytesRead === "number") c.bytesRead = e.socket.bytesRead;
264	 264 │     if (typeof e.message === "string" && e.message) c.message = redactSecrets(e.message);
265	 265 │     out.push(c);
266	 266 │     if (Array.isArray(e.errors)) for (const sub of e.errors) visit(sub);
267	 267 │     visit(e.cause);
268	 268 │   };
269	 269 │   visit(err?.cause);
270	 270 │   return out;
271	 271 │ }
272	 272 │ 
273	 273 │ function formatCause(chain: TransportCause[]): string {
274	 274 │   if (!chain.length) return "";
275	 275 │   return ` (cause: ${chain.map((c) => [c.code, c.message].filter(Boolean).join(": ") || c.name).join(" <- ")})`;
276	 276 │ }
277	 277 │ 
278	 278 │ /** Classify a fetch/read rejection. `operatorSignal` distinguishes operator abort from the request timeout. */
279	 279 │ function classifyTransportError(err: any, operatorSignal: AbortSignal | undefined, requestId: string, phase: "connect" | "stream", partialText = ""): InferenceError {
280	 280 │   if (err instanceof InferenceError) return err;
281	 281 │   if (operatorSignal?.aborted) return abortedError(requestId, partialText);
282	 282 │   const transportCause = transportCauseChain(err);
283	 283 │   const timedOut = err?.name === "TimeoutError";
284	 284 │   const classification = classifyTransportFailure(transportCause, phase, timedOut);
285	 285 │   if (timedOut) {
286	 286 │     return new InferenceError("timeout", "transport", `Inference request timed out: ${err.message}${formatCause(transportCause)}`, { requestId, partialText, transportCause, ...classification });
287	 287 │   }
288	 288 │   const msg = `${err?.message || String(err)}${formatCause(transportCause)}`;
289	 289 │   return phase === "stream"
290	 290 │     ? new InferenceError("stream_interrupted", "transport", `Inference stream interrupted before completion: ${msg}`, { requestId, partialText, transportCause, ...classification })
291	 291 │     : new InferenceError("network_error", "transport", `Inference request failed: ${msg}`, { requestId, transportCause, ...classification });
292	 292 │ }
