478	 478 │   private async executeWithFailover<T>(
479	 479 │     operationName: string,
480	 480 │     operation: (endpoint: string) => Promise<T>
481	 481 │   ): Promise<T> {
482	 482 │     const total = this.endpoints.length;
483	 483 │     let lastError: Error | null = null;
484	 484 │ 
485	 485 │     for (let attempt = 0; attempt < total; attempt++) {
486	 486 │       const idx = (this.activeEndpointIndex + attempt) % total;
487	 487 │       const currentEp = this.endpoints[idx];
488	 488 │ 
489	 489 │       try {
490	 490 │         const result = await operation(currentEp);
491	 491 │         if (idx !== this.activeEndpointIndex) {
492	 492 │           console.warn(
493	 493 │             pc.yellow(`\n⚡ Failover: Active inference endpoint switched to ${currentEp}`)
494	 494 │           );
495	 495 │           this.activeEndpointIndex = idx;
496	 496 │         }
497	 497 │         return result;
498	 498 │       } catch (err: any) {
499	 499 │         lastError = err;
500	 500 │         if (err instanceof InferenceError && !err.failoverEligible) throw err;
501	 501 │         if (total > 1 && attempt < total - 1) {
502	 502 │           const nextIdx = (idx + 1) % total;
503	 503 │           console.warn(
504	 504 │             pc.dim(
505	 505 │               `⚠️ [Failover] ${operationName} failed on ${currentEp} (${err.message}). Trying backup endpoint ${this.endpoints[nextIdx]}...`
506	 506 │             )
