563	 563 │     const total = this.endpoints.length;
564	 564 │     const start = opts.preferAlternate && total > 1 ? (this.activeEndpointIndex + 1) % total : this.activeEndpointIndex;
565	 565 │     let last: ProbeResult = { available: false, condition: "TEMPORARILY_UNAVAILABLE" };
566	 566 │     for (let i = 0; i < total; i++) {
567	 567 │       const idx = (start + i) % total;
568	 568 │       const timeout = AbortSignal.timeout(opts.timeoutMs ?? 5_000);
569	 569 │       try {
570	 570 │         const res = await fetch(`${this.endpoints[idx]}/models`, {
571	 571 │           headers: this.authorization(this.endpoints[idx]),
572	 572 │           signal: signal ? AbortSignal.any([timeout, signal]) : timeout,
573	 573 │         });
574	 574 │         const body = await res.text().catch(() => "");
575	 575 │         if (res.status < 500 && res.status !== 429 && res.status !== 408) {
576	 576 │           this.activeEndpointIndex = idx;
