 248 │ /** Walk `err.cause` (and AggregateError members): fetch reports only "fetch failed"/"terminated" at the top. */
 249 │ export function transportCauseChain(err: any): TransportCause[] {
 250 │   const out: TransportCause[] = [];
 251 │   const seen = new Set<unknown>();
 252 │   const visit = (e: any): void => {
 253 │     if (!e || typeof e !== "object" || seen.has(e) || out.length >= 8) return;
 254 │     seen.add(e);
 255 │     const c: TransportCause = {};
 256 │     if (typeof e.name === "string") c.name = e.name;
 257 │     if (typeof e.code === "string") c.code = e.code;
 258 │     if (typeof e.errno === "number") c.errno = e.errno;
 259 │     if (typeof e.syscall === "string") c.syscall = e.syscall;
 260 │     if (typeof e.address === "string") c.address = e.address;
 261 │     if (typeof e.port === "number") c.port = e.port;
 262 │     if (typeof e.socket?.bytesWritten === "number") c.bytesWritten = e.socket.bytesWritten;
 263 │     if (typeof e.socket?.bytesRead === "number") c.bytesRead = e.socket.bytesRead;
 264 │     if (typeof e.message === "string" && e.message) c.message = redactSecrets(e.message);
 265 │     out.push(c);
 266 │     if (Array.isArray(e.errors)) for (const sub of e.errors) visit(sub);
 267 │     visit(e.cause);
 268 │   };
 269 │   visit(err?.cause);
 270 │   return out;
 271 │ }
