 273 │ function formatCause(chain: TransportCause[]): string {
 274 │   if (!chain.length) return "";
 275 │   return ` (cause: ${chain.map((c) => [c.code, c.message].filter(Boolean).join(": ") || c.name).join(" <- ")})`;
 276 │ }
