 278 │ /** Classify a fetch/read rejection. `operatorSignal` distinguishes operator abort from the request timeout. */
 279 │ function classifyTransportError(err: any, operatorSignal: AbortSignal | undefined, requestId: string, phase: "connect" | "stream", partialText = ""): InferenceError {
 280 │   if (err instanceof InferenceError) return err;
 281 │   if (operatorSignal?.aborted) return abortedError(requestId, partialText);
 282 │   const transportCause = transportCauseChain(err);
 283 │   const timedOut = err?.name === "TimeoutError";
 284 │   const classification = classifyTransportFailure(transportCause, phase, timedOut);
 285 │   if (timedOut) {
 286 │     return new InferenceError("timeout", "transport", `Inference request timed out: ${err.message}${formatCause(transportCause)}`, { requestId, partialText, transportCause, ...classification });
 287 │   }
 288 │   const msg = `${err?.message || String(err)}${formatCause(transportCause)}`;
 289 │   return phase === "stream"
 290 │     ? new InferenceError("stream_interrupted", "transport", `Inference stream interrupted before completion: ${msg}`, { requestId, partialText, transportCause, ...classification })
 291 │     : new InferenceError("network_error", "transport", `Inference request failed: ${msg}`, { requestId, transportCause, ...classification });
 292 │ }
