    try {
      const client = new LocalLlmClient(cfg("openrouter", `${m.url}/api/v1`, { model: "anthropic/claude-x", workspace: ws }));
      const out = await client.chatCompletionStream(msgs, TOOLS, undefined, "req-or-1");
