      assert.match(persisted, /"requestId":"req-or-1"/);
      assert.doesNotMatch(persisted, /sk-cloud-key/, "receipts never hold credentials");
    } finally { await m.close(); fs.rmSync(ws, { recursive: true, force: true }); }
