    try {
      const e = await rejects(new LocalLlmClient(cfg("openrouter", `${m.url}/api/v1`)).chatCompletionStream(msgs, [], undefined));
      assert.equal(e.kind, "provider_error_frame");
    } finally { await m.close(); }
  });
});

