  test("Anthropic uses x-api-key + anthropic-version, never Authorization or the appliance X-Task-Class", async () => {
    const m = await mock((_s, res) => json(res, 200, { content: [{ type: "text", text: "ok" }], stop_reason: "end_turn" }));
