    try {
      const e = await rejects(new LocalLlmClient(cfg("anthropic", `${m.url}/v1`)).chatCompletion(msgs, []));
      assert.equal(e.kind, "network_error");
      assert.equal(other.seen.length, 0);
    } finally { await m.close(); await other.close(); }
