// Scripted Anthropic Messages mock: answers the verify flow and a one-tool agent task.
import http from "node:http";
const ev = (o) => `event: ${o.type}\ndata: ${JSON.stringify(o)}\n\n`;
const start = ev({ type: "message_start", message: { id: "msg_x", model: "claude-mock", usage: { input_tokens: 10, output_tokens: 1 } } });
const text = (i, t) => ev({ type: "content_block_start", index: i, content_block: { type: "text", text: "" } }) + ev({ type: "content_block_delta", index: i, delta: { type: "text_delta", text: t } }) + ev({ type: "content_block_stop", index: i });
const tool = (i, id, name, input) => ev({ type: "content_block_start", index: i, content_block: { type: "tool_use", id, name, input: {} } }) + ev({ type: "content_block_delta", index: i, delta: { type: "input_json_delta", partial_json: JSON.stringify(input) } }) + ev({ type: "content_block_stop", index: i });
const end = (s) => ev({ type: "message_delta", delta: { stop_reason: s }, usage: { output_tokens: 7 } }) + ev({ type: "message_stop" });
const log = [];
http.createServer((req, res) => {
  let b = ""; req.on("data", (c) => (b += c)); req.on("end", () => {
    const body = b ? JSON.parse(b) : {};
    log.push({ path: req.url, key: req.headers["x-api-key"], auth: req.headers.authorization ?? null, taskClass: req.headers["x-task-class"] ?? null });
    if (req.url === "/log") { res.end(JSON.stringify(log)); return; }
    if (req.method === "GET") { res.end(JSON.stringify({ data: [{ id: "claude-mock" }] })); return; }
    res.writeHead(200, { "Content-Type": "text/event-stream" });
    const msgs = body.messages ?? [];
    const last = msgs[msgs.length - 1];
    const lastText = JSON.stringify(last?.content ?? "");
    const hasResult = Array.isArray(last?.content) && last.content.some((c) => c.type === "tool_result");
    if (/READY/.test(lastText)) return res.end(start + text(0, "READY") + end("end_turn"));
    const nonce = /token \\"(n[0-9a-f]+)\\"/.exec(lastText)?.[1];
    if (nonce && !hasResult) return res.end(start + tool(0, "toolu_e", "echo_token", { token: nonce }) + end("tool_use"));
    if (hasResult && body.tools?.some((t) => t.name === "echo_token")) {
      const r = last.content.find((c) => c.type === "tool_result").content;
