import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import * as readline from "node:readline";
import { fileURLToPath } from "node:url";
import { Command } from "commander";
import type { AgentObserver } from "./agent.js";
import { CheckpointManager } from "./checkpoint.js";
import { autoDetectModel, buildConfig, loadEnvironment } from "./config.js";
import { ApplicationCore } from "./core/app.js";
import { redactForPersistence } from "./core/persistence_protection.js";
import { TurnResult, failedTurnFromError, lifecycleStatusForTurn, summarizeTurn } from "./core/turn.js";
import { getGitInfo } from "./git.js";
import { redactSecrets } from "./ui.js";
import { approvalReview } from "./approval_review.js";
import { EvidenceLedger, LastTurn, MAX_EVIDENCE, ReceiptSection, receiptSections, redactedJson } from "./evidence.js";
import {
  MAX_SLASH_OUTPUT,
  PROTOCOL_VERSION,
  ProtocolError,
  SidecarCommand,
  SidecarEvent,
  capText,
  encodeEvent,
  parseCommand,
  projectTurn,
  providerRecoveryNotice,
  stripEscapes,
  toolSubject,
  toolSummary,
} from "./protocol.js";
import { SlashHost, SlashOutcome, SlashSpec, errorText, findSlash, slashCatalog } from "./slash/catalog.js";
import { routeSlash } from "./slash/router.js";

export interface SidecarOptions {
  app: ApplicationCore;
  /** Receives complete protocol lines (each ends with "\n"). */
  write: (line: string) => void;
  mode: "auto" | "review";
  onShutdown?: () => void;
  .name("harness")
  .description("Nexus Code - Custom Autonomous Coding Harness for Local AI (LM Studio / vLLM)")
  .version("1.2.1");

program
  .command("repl")
  .description("Start interactive coding session (REPL / TUI)")
  .option("-e, --endpoint <url>", "Local LLM endpoint (default: $LOCAL_LLM_ENDPOINT)")
  .option("-m, --model <name>", "Model name identifier (default: active model in vLLM)")
  .option("-w, --workspace <path>", "Workspace directory (default: current directory)")
  .option("-s, --max-steps <number>", "Maximum steps per turn (default: 30)")
  .option("-t, --temperature <number>", "Model temperature (default: 0.2)")
  .option("--shell <type>", "Linux shell to use: bash, zsh, or sh (default: bash)", "bash")
  .option("--fallback <urls>", "Comma-separated fallback LLM endpoints if primary is unavailable")
  .option("--context-limit <tokens>", "Model context window limit in tokens (default: 65536)")
  .option("--dry-run", "Simulate file modifications without writing changes to disk")
#!/usr/bin/env bash
set -euo pipefail

# Resolve symlinks so the script works when symlinked into /usr/local/bin or ~/bin
SOURCE="${BASH_SOURCE[0]}"
while [ -h "$SOURCE" ]; do
  DIR="$(cd -P "$(dirname "$SOURCE")" && pwd)"
  SOURCE="$(readlink "$SOURCE")"
  [[ $SOURCE != /* ]] && SOURCE="$DIR/$SOURCE"
done
SCRIPT_DIR="$(cd -P "$(dirname "$SOURCE")" && pwd)"
NODE_EXEC="${NODE_EXEC:-node}"

TUI_BIN="$SCRIPT_DIR/core/target/release/nexus-tui"

run_tui() {
  exec "$TUI_BIN" --live --sidecar "$SCRIPT_DIR/cli/dist/sidecar.js" --node "$NODE_EXEC" -- "$@"
}

# No arguments: the live TUI when it is built and both ends are a terminal; otherwise the readline REPL.
if [[ $# -eq 0 ]]; then
  if [[ -x "$TUI_BIN" && -t 0 && -t 1 ]]; then
    run_tui
  fi
  if [[ ! -x "$TUI_BIN" ]]; then
    echo "nexus: the live TUI is not built (run 'make build' in $SCRIPT_DIR); starting the REPL." >&2
  fi
  exec "$NODE_EXEC" "$SCRIPT_DIR/cli/dist/index.js" repl
elif [[ "$1" == "--repl" ]]; then
  shift
  exec "$NODE_EXEC" "$SCRIPT_DIR/cli/dist/index.js" repl "$@"
elif [[ "$1" == "--live" ]]; then
  shift
  if [[ ! -x "$TUI_BIN" ]]; then
    echo "nexus-tui is not built. Run 'make build' in $SCRIPT_DIR first." >&2
    exit 1
  fi
  run_tui "$@"
elif [[ "$1" == "check" ]] || [[ "$1" == "models" ]] || [[ "$1" == "sessions" ]] || [[ "$1" == "skills" ]] || [[ "$1" == "mcp" ]] || [[ "$1" == "plugins" ]] || [[ "$1" == "checkpoints" ]] || [[ "$1" == "audit" ]] || [[ "$1" == "serve-mcp" ]] || [[ "$1" == "run" ]] || [[ "$1" == "repl" ]] || [[ "$1" == "--help" ]] || [[ "$1" == "-h" ]] || [[ "$1" == "--version" ]] || [[ "$1" == "-V" ]]; then
  exec "$NODE_EXEC" "$SCRIPT_DIR/cli/dist/index.js" "$@"
