			ReasoningLevels:        levels,
			DefaultReasoningEffort: m.DefaultReasoningLevel,
			SupportsImages:         true,
		})
	}
	if len(models) == 0 {
		return nil, fmt.Errorf("the Codex model catalog was empty")
	}
	return models, nil
}
