            id,
            tool,
            subject,
            review,
        } => {
            let lines = review_lines(review.as_ref().unwrap_or(&Review::Unknown));
            self.overlay = Some(Overlay::Approval(Approval {
                id,
                tool,
                subject,
                lines,
                scroll: 0,
                opened: Instant::now(),
            }));
        }
