        Event::Notice { text } => self.transcript.push(Entry::Info(text)),
        Event::ToolDetail {
            id,
            status,
            args,
            output,
            duration_ms,
        } => {
            if let Some(Overlay::Detail(detail)) = &mut self.overlay
                && detail.request == id
            {
                detail.record = Loaded::Ready(ToolRecord {
                    status,
                    args,
                    output,
                    duration_ms,
                });
            }
