      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ code, code_verifier: pkce.verifier, code_challenge_method: "S256" }),
      signal: AbortSignal.any([signal, AbortSignal.timeout(30_000)]),
