    fn on_provider_result(&mut self, id: String, provider: String, success: bool, message: String) {
        if let Some(Overlay::Connect(flow)) = &mut self.overlay {
            let waiting = matches!(&flow.step, Step::Waiting { request, .. } if *request == id);
            if waiting {
