      setOAuthEndpoints({ githubDeviceCode: `${m.url}/device`, githubAccessToken: `${m.url}/token`, copilotToken: `${m.url}/copilot`, minPollMs: 5 });
      const flow = await startAuthFlow("copilot-device", new AbortController().signal);
