    await sleep(400);
    assert.ok(screenSince(mark).includes("Select model"), diag());
    assert.ok(screenSince(mark).includes("Connect Anthropic"), diag());

    // 2. ctrl+p: the connect panel; Anthropic is the third provider (openrouter, openai, anthropic, ...).
